                                                            `name`="fd", 
                                                            `title`="RM - CS<br>fit delta", 
                                                            `type`="number"),
                                                        list(
                                                            `name`="c", 
                                                            `title`="Commutability", 
                                                            `type`="text"))))}))$new(options=options))
                                    self$add(jmvcore::Preformatted$new(
                                        options=options,
                                        name="c",
                                        title="Conclusion"))}))$new(options=options))}))$new(options=options))
            self$add(jmvcore::Preformatted$new(
                options=options,
                name="summary",
                title="In summary"))}))

CommutabilityEP30ARegressionBase <- if (requireNamespace("jmvcore", quietly=TRUE)) R6::R6Class(
    "CommutabilityEP30ARegressionBase",
