#' Commutability (CLSI, EP30-A2-R)
#'
#' 
#' @param data .
#' @param csid .
#' @param csx .
#' @param csy .
#' @param rmid .
#' @param rmp .
#' @param rmx .
#' @param rmy .
#' @param ln .
#' @param alpha .
#' @param ol .
#' @param ncc .
#' @param mt .
#' @param unit .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$text} \tab \tab \tab \tab \tab a preformatted \cr
#'   \code{results$mr} \tab \tab \tab \tab \tab a preformatted \cr
#'   \code{results$abb} \tab \tab \tab \tab \tab a preformatted \cr
#'   \code{results$symbols} \tab \tab \tab \tab \tab a preformatted \cr
#'   \code{results$descriptive$olg} \tab \tab \tab \tab \tab a group \cr
#'   \code{results$descriptive$dtg} \tab \tab \tab \tab \tab a group \cr
#'   \code{results$descriptive$v} \tab \tab \tab \tab \tab a group \cr
#'   \code{results$ccs$t} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$ccs$c} \tab \tab \tab \tab \tab a preformatted \cr
#'   \code{results$oci} \tab \tab \tab \tab \tab a preformatted \cr
#'   \code{results$c$deming} \tab \tab \tab \tab \tab a group \cr
#'   \code{results$c$ols} \tab \tab \tab \tab \tab a group \cr
#'   \code{results$c$pb} \tab \tab \tab \tab \tab a group \cr
#'   \code{results$summary} \tab \tab \tab \tab \tab a preformatted \cr
#' }
#'
#' @export
CommutabilityEP30ARegression <- function(
    data,
    csid,
    csx,
    csy,
    rmid,
    rmp,
    rmx,
    rmy,
    ln,
    alpha = 0.05,
    ol = TRUE,
    ncc = 5,
    mt = "HbA1c",
    unit = "mg/L") {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("CommutabilityEP30ARegression requires jmvcore to be installed (restart may be required)")

    if ( ! missing(csid)) csid <- jmvcore::resolveQuo(jmvcore::enquo(csid))
    if ( ! missing(csx)) csx <- jmvcore::resolveQuo(jmvcore::enquo(csx))
    if ( ! missing(csy)) csy <- jmvcore::resolveQuo(jmvcore::enquo(csy))
    if ( ! missing(rmid)) rmid <- jmvcore::resolveQuo(jmvcore::enquo(rmid))
    if ( ! missing(rmp)) rmp <- jmvcore::resolveQuo(jmvcore::enquo(rmp))
    if ( ! missing(rmx)) rmx <- jmvcore::resolveQuo(jmvcore::enquo(rmx))
    if ( ! missing(rmy)) rmy <- jmvcore::resolveQuo(jmvcore::enquo(rmy))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(csid), csid, NULL),
            `if`( ! missing(csx), csx, NULL),
            `if`( ! missing(csy), csy, NULL),
            `if`( ! missing(rmid), rmid, NULL),
            `if`( ! missing(rmp), rmp, NULL),
            `if`( ! missing(rmx), rmx, NULL),
            `if`( ! missing(rmy), rmy, NULL))


    options <- CommutabilityEP30ARegressionOptions$new(
        csid = csid,
        csx = csx,
        csy = csy,
        rmid = rmid,
        rmp = rmp,
        rmx = rmx,
        rmy = rmy,
        ln = ln,
        alpha = alpha,
        ol = ol,
        ncc = ncc,
        mt = mt,
        unit = unit)

    analysis <- CommutabilityEP30ARegressionClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

